<script setup lang="ts">
import Modal from "@papilio/ui/Modal.vue";
import { onMounted, ref, watch } from "vue";
import { useRouter } from "vue-router";
import { useAuth } from "@papilio/auth";
import { item, query, request, type Page, type Staff, type StaffRole, type StaffRoleRevision, type StaffScopeCatalog } from "@papilio/api";
import { faDate, faNumber } from "@papilio/ui";
import StaffScopeEditor from "../components/StaffScopeEditor.vue";
const auth = useAuth();const router=useRouter();const selectionLoading=ref(false); const rows = ref<StaffRole[]>([]); const q = ref(""); const status = ref(""); const page = ref(1); const pages = ref(1); const total = ref(0);
const selected = ref<StaffRole|null>(null); const title = ref(""); const active = ref(true); const scopes = ref<string[]>([]); const reason = ref("");
const code = ref(""); const newTitle = ref(""); const newActive = ref(true); const newScopes = ref<string[]>([]); const newReason = ref("");
const catalog = ref<StaffScopeCatalog|null>(null); const history = ref<StaffRoleRevision[]>([]); const historyPage = ref(1); const historyPages = ref(1); const historyError = ref(""); const historyLoading = ref(false);
const members=ref<Staff[]>([]);const memberQ=ref("");const memberPage=ref(1);const memberPages=ref(1);const memberError=ref("");const memberLoading=ref(false);let memberVersion=0;
const loading = ref(false); const busy = ref(false); const error = ref(""); const notice = ref(""); let readVersion=0; let selectionVersion=0; let historyVersion=0;
function message(cause: unknown): string { return cause instanceof Error ? cause.message : "The operation failed. Please try again."; }
async function load(): Promise<void> { const version=++readVersion; loading.value=true; error.value=""; try { const result=await request<Page<StaffRole>>(`/v1/admin/roles?${query({q:q.value,page:page.value,is_active:status.value===""?undefined:status.value==="active"})}`); if(version!==readVersion)return; rows.value=result.data; pages.value=result.meta.pager?.total_pages??1; total.value=result.meta.pager?.total_items??0; } catch(cause) { if(version===readVersion)error.value=message(cause); } finally { if(version===readVersion)loading.value=false; } }
async function loadHistory(): Promise<void> { const row=selected.value; if(!row)return; const version=++historyVersion; historyLoading.value=true; historyError.value=""; try { const result=await request<Page<StaffRoleRevision>>(`/v1/admin/roles/${row.id}/history?${query({page:historyPage.value})}`); if(version!==historyVersion||selected.value?.id!==row.id)return; history.value=result.data; historyPages.value=result.meta.pager?.total_pages??1; } catch(cause) { if(version===historyVersion)historyError.value=message(cause); } finally { if(version===historyVersion)historyLoading.value=false; } }
async function loadMembers(): Promise<void>{const row=selected.value;if(!row)return;const version=++memberVersion;memberLoading.value=true;memberError.value="";try{const result=await request<Page<Staff>>(`/v1/admin/roles/${row.id}/members?${query({q:memberQ.value,page:memberPage.value})}`);if(version!==memberVersion||selected.value?.id!==row.id)return;members.value=result.data;memberPages.value=result.meta.pager?.total_pages??1;}catch(cause){if(version===memberVersion)memberError.value=message(cause);}finally{if(version===memberVersion)memberLoading.value=false;}}
async function select(row: StaffRole, preserve=false): Promise<void> { if(busy.value||selectionLoading.value)return; const version=++selectionVersion;selectionLoading.value=true;error.value="";if(!preserve)selected.value=null; try { const fresh=await item<StaffRole>(`/v1/admin/roles/${row.id}`); if(version!==selectionVersion)return; selected.value=fresh; if(!preserve){title.value=fresh.title;active.value=fresh.is_active;scopes.value=[...fresh.scopes];reason.value="";} history.value=[];historyPage.value=1;members.value=[];memberPage.value=1;void loadMembers();void loadHistory(); } catch(cause){if(version===selectionVersion)error.value=message(cause);}finally{if(version===selectionVersion)selectionLoading.value=false;} }
async function create(): Promise<void> { if(busy.value||selectionLoading.value||!auth.can("staff","create"))return;busy.value=true;error.value="";notice.value="";try { const result=await item<StaffRole>("/v1/admin/roles","POST",{code:code.value,title:newTitle.value,is_active:newActive.value,scopes:newScopes.value,reason:newReason.value});code.value="";newTitle.value="";newScopes.value=[];newReason.value="";selected.value=result;title.value=result.title;active.value=result.is_active;scopes.value=[...result.scopes];reason.value="";historyPage.value=1;createOpen.value=false;notice.value="Role created.";await load();await loadHistory();await loadMembers();}catch(cause){error.value=message(cause);}finally{busy.value=false;} }
async function save(): Promise<void> { const row=selected.value;if(!row||busy.value||selectionLoading.value||!auth.can("staff","update"))return;busy.value=true;error.value="";notice.value="";try { selected.value=await item<StaffRole>(`/v1/admin/roles/${row.id}`,"PUT",{title:title.value,is_active:active.value,scopes:scopes.value,expected_revision:row.revision,reason:reason.value});notice.value="Role saved. Member permissions update on their next request.";reason.value="";await load();await loadHistory();await loadMembers();await auth.restore();if(!auth.session||!auth.can("staff"))await router.push(auth.session?"/":"/login");}catch(cause){error.value=message(cause);}finally{busy.value=false;} }
watch(memberQ,()=>{memberPage.value=1;void loadMembers();});
watch([q,status],()=>{page.value=1;void load();});
onMounted(async()=>{void load();try{catalog.value=await item<StaffScopeCatalog>("/v1/admin/staff/scope-catalog");}catch(cause){error.value=message(cause);}});
const createOpen=ref(false);
</script>
<template>
<div class="page-head"><div><p class="eyebrow">TEAM PERMISSIONS</p><h1>Roles</h1><p class="subtitle">Active role permissions combine with an account's direct permissions. Inactive roles grant no access.</p></div><RouterLink class="btn secondary" to="/staff">Staff and role assignments</RouterLink><button v-if="auth.can('staff','create')" class="btn" :disabled="busy" @click="createOpen=true">+ Create role</button></div>
<p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p>
<div :class="{split:!!selected}"><div class="card"><div class="card-pad form-grid"><label class="field"><span>Search role name or code</span><input v-model="q" maxlength="100" /></label><label class="field"><span>Role status</span><select v-model="status"><option value="">All</option><option value="active">Active</option><option value="inactive">Inactive</option></select></label><button class="btn secondary" :disabled="loading||busy" @click="load">Refresh list</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Role</th><th>Status</th><th>Revision</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" :class="{'selected-row':selected?.id===row.id}" tabindex="0" @click="select(row)" @keydown.enter="select(row)"><td>{{row.title}}<small dir="ltr">{{row.code}}</small></td><td>{{row.is_active?'Active':'Inactive'}}</td><td>{{faNumber(row.revision)}}</td></tr></tbody></table><div v-if="loading" class="empty">Loading…</div><div v-else-if="!rows.length&&!error" class="empty">No roles found.</div></div><div class="pager"><button :disabled="page<=1||loading||busy" @click="page--;load()">‹</button><span>{{faNumber(page)}} · {{faNumber(total)}} Role</span><button :disabled="page>=pages||loading||busy" @click="page++;load()">›</button></div></div>
<div class="stack"><div v-if="selected" class="card card-pad"><h2>{{selected.title}} · Revision {{faNumber(selected.revision)}}</h2><form class="form-grid" @submit.prevent="save"><label class="field"><span>Role name</span><input v-model="title" minlength="2" maxlength="100" required :disabled="busy||!auth.can('staff','update')" /></label><label><input v-model="active" type="checkbox" :disabled="busy||!auth.can('staff','update')" /> Role Active</label><StaffScopeEditor v-model="scopes" :catalog="catalog" :allow-owner="false" :disabled="busy||!auth.can('staff','update')" /><label v-if="auth.can('staff','update')" class="field"><span>Change reason</span><input v-model="reason" minlength="3" maxlength="250" required :disabled="busy" /></label><button v-if="auth.can('staff','update')" class="btn" :disabled="busy||selectionLoading||!catalog||reason.trim().length<3">Save role</button><button type="button" class="btn secondary" :disabled="busy||selectionLoading" @click="select(selected,true)">Refresh and retain draft</button></form>
<h3>Role members</h3><label class="field"><span>Search members</span><input v-model="memberQ" maxlength="64" /></label><p v-if="memberError" class="message error">{{memberError}}</p><button class="btn secondary" :disabled="memberLoading" @click="loadMembers">Refresh members</button><p v-if="memberLoading">Loading…</p><div v-for="row in members" :key="row.id" class="hint-box"><RouterLink :to="{path:'/staff',query:{staff_id:row.id}}">{{row.username}} · {{row.is_active?'Active':'Inactive'}}</RouterLink></div><p v-if="!members.length&&!memberLoading&&!memberError">No members assigned.</p><div class="pager"><button :disabled="memberPage<=1||memberLoading" @click="memberPage--;loadMembers()">‹</button><span>{{faNumber(memberPage)}}</span><button :disabled="memberPage>=memberPages||memberLoading" @click="memberPage++;loadMembers()">›</button></div>
<h3>Role history</h3><p v-if="historyError" class="message error">{{historyError}}</p><button class="btn secondary" :disabled="historyLoading" @click="loadHistory">Refresh history</button><p v-if="historyLoading">Loading…</p><div v-for="row in history" :key="row.id" class="hint-box"><strong>Revision {{faNumber(row.revision)}} · {{row.title}} · {{row.is_active?'Active':'Inactive'}}</strong><p>{{row.reason}} · Staff {{faNumber(row.staff_id)}} · {{faDate(row.created_at)}}</p><p dir="ltr">{{row.scopes.join(', ')||'—'}}</p></div><div class="pager"><button :disabled="historyPage<=1||historyLoading" @click="historyPage--;loadHistory()">‹</button><span>{{faNumber(historyPage)}}</span><button :disabled="historyPage>=historyPages||historyLoading" @click="historyPage++;loadHistory()">›</button></div></div>
<Modal v-if="auth.can('staff','create')" v-model="createOpen" title="Create role" :busy="busy" wide><p v-if="error" class="message error" role="alert">{{error}}</p><form class="form-grid" @submit.prevent="create"><label class="field"><span>Unique role code</span><input v-model="code" dir="ltr" pattern="[a-z][a-z0-9_-]+" minlength="2" maxlength="64" required :disabled="busy" /></label><label class="field"><span>Role name</span><input v-model="newTitle" minlength="2" maxlength="100" required :disabled="busy" /></label><label><input v-model="newActive" type="checkbox" :disabled="busy" /> Role Active</label><StaffScopeEditor v-model="newScopes" :catalog="catalog" :allow-owner="false" :disabled="busy" /><label class="field"><span>Creation reason</span><input v-model="newReason" minlength="3" maxlength="250" required :disabled="busy" /></label><button class="btn" :disabled="busy||selectionLoading||!catalog||newReason.trim().length<3">Create role</button></form><p class="hint-box">System owner access is assigned directly to accounts and cannot be included in a shared role.</p></Modal></div></div>
</template>
<style scoped>small{display:block;color:var(--muted)}input[type=checkbox]{width:auto;min-height:0}</style>
